using HarmonyLib;
using HistoricalRimWorld.Characters;
using HistoricalRimWorld.Factions;
using HistoricalRimWorld.Scenarios.EasternZhou;
using RimWorld;
using Verse;

namespace HistoricalRimWorld.Patches.Characters
{
    /// <summary>Uses the Eastern Zhou Chinese name pool for pawns generated by its player faction.</summary>
    [HarmonyPatch(typeof(PawnBioAndNameGenerator), nameof(PawnBioAndNameGenerator.GiveAppropriateBioAndNameTo))]
    internal static class HistoricalEasternZhouPawnNamePatch
    {
        private static void Postfix(Pawn pawn, FactionDef factionType)
        {
            if (pawn == null || factionType == null
                || !HistoricalFactionGenerationContext.TryGetSelectedSetup(out HistoricalPlayableScenarioSetupDef setup)
                || setup.startingNamePool == null
                || !HistoricalFactionGenerationContext.IsSelectedPlayerFaction(factionType)) return;

            pawn.Name = HistoricalChineseNameGenerator.Generate(setup.startingNamePool);
        }
    }
}
